-- [selectMemberContact] ACTUAL_SOURCE_MAPPER; source=pms-module-integration/src/main/resources/base-sync-source/P31SourceMapper.xml
SELECT m.id AS sourceId,m.projectId AS originalProjectId,m.projectType,m.memberRole,m.memberCode,m.memberName,m.phoneNum,m.email,m.fromFlag,m.createTime,m.createBy AS source_creator,m.updateTime,m.updateBy AS source_updater,m.effectiveFrom,m.effectiveTo FROM pm_project_member m WHERE m.projectType='10' AND m.memberRole IN ('10','20','30','60')  /* CHOOSE  */ /* WHEN test=projectKeys != null and !projectKeys.isEmpty() */ AND m.projectId IN  /* FOREACH collection=projectKeys; item=key; open=(; close=); separator=, */ (#{key}) /* repeat with separator=,; END FOREACH */ /* END WHEN */  /* OTHERWISE  */ AND 1=0 /* END OTHERWISE */ /* END CHOOSE */  ORDER BY m.id LIMIT #{limit};

