-- cn.iocoder.yudao.module.pms.integration.basesync.task.P31MemberContactSyncTask$TargetMapper.selectMembers; pms-module-integration/src/main/resources/mapper/basesync/P31TargetMapper.xml:4; kind=select
SELECT r.`id`,r.`project_id`,r.`user_id`,r.`employee_no`,r.`member_name`,r.`company_id`,r.`company_code`,r.`company_name`,r.`department_id`,r.`department_code`,r.`department_name`,r.`member_role`,r.`assignment_type`,r.`site_id`,r.`responsibility`,r.`change_reason`,r.`effective_from`,r.`effective_to`,r.`status`,r.`version`,r.`creator`,r.`create_time`,r.`updater`,r.`update_time`,r.`deleted`,r.`deleted_time`,r.`tenant_id`,r.`remark`,r.`end_reason`,r.`member_code`,r.`phone_number`,r.`email`,r.`registration_source`,r.`authorization_confirmed`,(b.id IS NOT NULL) AS owned FROM proj_project_member_assignment r LEFT JOIN int_base_sync_task task ON task.tenant_id=r.tenant_id AND task.task_code='BASE_P31' AND task.connection_id=#{query.connectionId} AND task.deleted=FALSE LEFT JOIN int_base_sync_binding b ON b.tenant_id=r.tenant_id AND b.task_id=task.id AND b.deleted=FALSE AND b.object_key='MEMBER_HISTORY' AND b.target_id=r.id WHERE r.tenant_id=#{query.tenantId}  /* CHOOSE  */ /* WHEN test=query.projectIds != null and !query.projectIds.isEmpty() */ AND r.project_id IN  /* FOREACH collection=query.projectIds; item=id; open=(; close=); separator=, */ (#{id}) /* repeat with separator=,; END FOREACH */ /* END WHEN */  /* OTHERWISE  */ AND 1=0 /* END OTHERWISE */ /* END CHOOSE */  ORDER BY r.id LIMIT #{query.limit} /* IF test=!query.preview */ FOR UPDATE /* END IF */;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P31MemberContactSyncTask$TargetMapper.selectContacts; pms-module-integration/src/main/resources/mapper/basesync/P31TargetMapper.xml:6; kind=select
SELECT r.`id`,r.`project_id`,r.`customer_id`,r.`customer_contact_id`,r.`name`,r.`department`,r.`title`,r.`mobile`,r.`phone`,r.`email`,r.`primary_flag`,r.`primary_set_time`,r.`status`,r.`remark`,r.`version`,r.`creator`,r.`create_time`,r.`updater`,r.`update_time`,r.`deleted`,r.`deleted_by`,r.`deleted_at`,r.`tenant_id`,r.`active_primary_project_id`,r.`project_party_id`,r.`contact_code`,r.`registration_source`,r.`effective_from`,r.`effective_to`,(b.id IS NOT NULL) AS owned FROM cus_project_customer_contact_relation r LEFT JOIN int_base_sync_task task ON task.tenant_id=r.tenant_id AND task.task_code='BASE_P31' AND task.connection_id=#{query.connectionId} AND task.deleted=FALSE LEFT JOIN int_base_sync_binding b ON b.tenant_id=r.tenant_id AND b.task_id=task.id AND b.deleted=FALSE AND b.object_key='CONTACT_HISTORY' AND b.target_id=r.id WHERE r.tenant_id=#{query.tenantId}  /* CHOOSE  */ /* WHEN test=query.projectIds != null and !query.projectIds.isEmpty() */ AND r.project_id IN  /* FOREACH collection=query.projectIds; item=id; open=(; close=); separator=, */ (#{id}) /* repeat with separator=,; END FOREACH */ /* END WHEN */  /* OTHERWISE  */ AND 1=0 /* END OTHERWISE */ /* END CHOOSE */  ORDER BY r.id LIMIT #{query.limit} /* IF test=!query.preview */ FOR UPDATE /* END IF */;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P31MemberContactSyncTask$TargetMapper.selectFinalCustomers; pms-module-integration/src/main/resources/mapper/basesync/P31TargetMapper.xml:8; kind=select
SELECT r.id,r.project_id,r.source_record_key FROM proj_project_party r WHERE r.tenant_id=#{query.tenantId} AND r.deleted=FALSE AND r.party_role='FINAL_CUSTOMER' AND r.source_system='DPPMS' AND r.source_table='pm_project_header'  /* CHOOSE  */ /* WHEN test=query.projectIds != null and !query.projectIds.isEmpty() */ AND r.project_id IN  /* FOREACH collection=query.projectIds; item=id; open=(; close=); separator=, */ (#{id}) /* repeat with separator=,; END FOREACH */ /* END WHEN */  /* OTHERWISE  */ AND 1=0 /* END OTHERWISE */ /* END CHOOSE */  /* IF test=!query.preview */ FOR UPDATE /* END IF */;

